using System;
class Program{
static int n;static void C(bool v,string s){if(!v)throw new Exception(s);n++;}
class Setup{public World W=new World();public EntityPlayer P;public ClientInfo Sender=new ClientInfo{ClientNumber=1,entityId=1};public Vector3i Pos=new Vector3i(1,2,3);public BlockPlantGrowingRebirth Crop=new BlockPlantGrowingRebirth{nextPlant=new BlockValue{type=3}};public BlockValue Target,Old=new BlockValue{type=0};public TileEntityPlantGrowingRebirth T=new TileEntityPlantGrowingRebirth{PlantIncarnation=50,StateRevision=3};public SeedPlacementSessionAuthority.Reservation R;public SeedPlacementOriginalCommandReview Command;
public Setup(){AdvancedFarmingHoverTextService.Reset();P=new EntityPlayer{entityId=1,world=W};W.Actors[1]=P;GameManager.Instance=new GameManager{World=W};SingletonMonoBehaviour<ConnectionManager>.Instance=new ConnectionManager();SingletonMonoBehaviour<ConnectionManager>.Instance.Clients.Entries[1]=Sender;Target=new BlockValue{type=2,meta=9,Block=Crop};W.Blocks[Pos]=Old;SeedPlacementSessionAuthority.TryIssue(Sender,W,out var epoch);SeedPlacementSessionAuthority.TryReserve(Sender,W,epoch,1,out R);Command=SeedPlacementOriginalCommandReview.Capture(epoch,1,1,1,new SeedPlacementIntentCodecReview.Intent{Slot=0,Position=Pos,Target=Target,ExpectedOld=Old,Seed=new byte[]{1},Flags=0x15});}
public AdvancedFarmingRemotePlantingAdmissionReview.RemoteScope Begin()=>AdvancedFarmingRemotePlantingAdmissionReview.Begin(R,Command,W,P);
